mapper.delete:
DELETE FROM
	sync_emp_master_${tempDomainId}

	COMPANY_CD = #{companyCd}
	AND DOMAIN_ID = #{domainId}

mapper.insert:
INSERT INTO 
	sync_emp_master_${tempDomainId} (
		SYNC_DATE
		, DOMAIN_ID
		, COMPANY_CD
		, EMAIL
		, EMP_NM
		, EMP_ENG_NM
		, EMP_NO
		, POS_CD
		, DEPT_CD
		, ENTER_DT
		, QUIT_DT
		, MANUAL_MNG_YN
		, HIDDEN_YN
		, EMP_STATUS_CD
		, JOB_TEL_NO
		, MOBILE_TEL_NO
		, UPDATE_USR
		, UPDATE_DT
		, CREATE_USR
		, CREATE_DT
	)
VALUES 

(
	DATE_FORMAT(now(), '%Y-%m-%d')
	, #{item.domainName}
	, #{item.company}
	, #{item.email}
	, #{item.name}
	, #{item.engName}
	, #{item.empNo}
	, #{item.positionCode}
	, #{item.deptCode}
	, #{item.entryDate}
	, #{item.quitDate}
	, #{item.manualMngYn}
	, #{item.hiddenYn}
	, #{item.stateStatusCode}
	, #{item.jobTelNo}
	, #{item.mobileTelNo}
	, 'SYSTEM'
	, now()
	, 'SYSTEM'
	, now()
)

