INSERT INTO 
	sync_log_${tempDomainId} (
		SYNC_DIV
		, AUTO_DIV
		, SYNC_DATE
		, DOMAIN_ID
		, COMPANY_CD
		, EMP_SYNC_RESULT
		, DEPT_SYNC_RESULT
		, CODE_SYNC_RESULT
		, UPDATE_USR
		, UPDATE_DT
		, CREATE_USR
		, CREATE_DT
	)
VALUES
(
	#{syncDiv}
	, #{autoDiv}
	, DATE_FORMAT(now(), '%Y-%m-%d')
	, #{domainId}
	, #{companyCd}
	, #{empSyncResult}
	, #{deptSyncResult}
	, #{codeSyncResult}
	, 'SYSTEM'
	, now()
	, 'SYSTEM'
	, now()
)

mapper.select:
SELECT S.SEQ , S.SYNC_DIV , S.AUTO_DIV , S.SYNC_DATE , C.COMPANY_NM , S.EMP_SYNC_RESULT , S.DEPT_SYNC_RESULT , S.CODE_SYNC_RESULT FROM sync_log_${tempDomainId} S INNER JOIN COMPANY_MASTER C ON (C.DOMAIN_ID = S.DOMAIN_ID AND C.COMPANY_CD = S.COMPANY_CD)
S.DOMAIN_ID = #{domainId} AND S.COMPANY_CD = #{companyCd}
AND S.SYNC_DIV = #{syncDiv}
AND S.AUTO_DIV = #{autoDiv}
ORDER BY SYNC_DATE DESC , SEQ DESC
LIMIT #{start}, #{length}

SELECT 
	COUNT(*)
FROM
	sync_log_${tempDomainId} S
	INNER JOIN COMPANY_MASTER C ON (C.DOMAIN_ID = S.DOMAIN_ID AND C.COMPANY_CD = S.COMPANY_CD)

	S.DOMAIN_ID = #{domainId}
	AND S.COMPANY_CD = #{companyCd}

		AND S.SYNC_DIV = #{syncDiv}


		AND S.AUTO_DIV = #{autoDiv}


ORDER BY SYNC_DATE
